import random
from app.scheduler import Scheduler as S2
from app import Scheduler
assert S2 is Scheduler

def reference_blocked(jobs, state):
    # naive: pending job is blocked if any dep is failed/blocked (transitively)
    changed = True
    while changed:
        changed = False
        for j, deps in jobs.items():
            if state[j] == 'pending' and any(state[d] in ('failed', 'blocked') for d in deps):
                state[j] = 'blocked'; changed = True
    return state

rng = random.Random(1)
for trial in range(2000):
    n = rng.randint(0, 12)
    names = [f'n{i:02d}' for i in range(n)]
    jobs = {}
    for i, name in enumerate(names):
        pool = names[:i]
        jobs[name] = rng.sample(pool, rng.randint(0, len(pool))) if pool else []
    cap = rng.randint(1, 4)
    s = Scheduler(jobs, max_parallel=cap)
    for _ in range(60):
        op = rng.random()
        if op < 0.4:
            r = s.ready()
            assert r == sorted(r)
            if r and s.state and sum(v == 'running' for v in s.statuses().values()) < cap:
                s.start(rng.choice(r))
        elif op < 0.9:
            running = [j for j, v in s.statuses().items() if v == 'running']
            if running:
                s.finish(rng.choice(running), success=rng.random() < 0.7)
        # invariants
        st = s.statuses()
        assert sum(v == 'running' for v in st.values()) <= cap
        for j, deps in jobs.items():
            if st[j] == 'pending':
                assert not any(st[d] in ('failed', 'blocked') for d in deps), (trial, j)
            if st[j] == 'running':
                assert all(st[d] == 'succeeded' for d in deps)
        ref = reference_blocked(jobs, dict(st))
        assert ref == st, (trial, ref, st)
        assert s.done() == (not any(v in ('pending', 'running') for v in st.values()))
print('fuzz ok')
EOF
